from pathlib import Path
import itsdangerous
def test_working_copy_origin():
    assert Path(itsdangerous.__file__).resolve().is_relative_to(Path('/workspace/src/itsdangerous'))

import itsdangerous, pytest
def test_roundtrip():
    signer = itsdangerous.URLSafeSerializer('probe-key')
    assert signer.loads(signer.dumps({'n': 1})) == {'n': 1}
def test_wrong_key_rejected():
    text = itsdangerous.URLSafeSerializer('probe-key').dumps('hello')
    with pytest.raises(itsdangerous.BadSignature):
        itsdangerous.URLSafeSerializer('different-key').loads(text)
